-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"عوامل تطور الأدب الحديث","passage":"يتأثر تاريخ الأدب بتحولات التعليم والصحافة والاتصال والترجمة وغيرها بحسب المرحلة، ولا يكفي وجود عامل واحد لتفسير كل تحول. مثال ضاديوم المستقل: يناقش طالبان أثر صحيفة جديدة في إتاحة القصص لقارئ أوسع، دون نسبة واقعة تاريخية بعينها.","prompt":"ما الذي يضبط تفسير تطور الأدب؟","correct":"ربط الشاهد بعامل تاريخي موثق","w1":"تخمين من عنوان","w2":"استخدام مثال مختلق كتاريخ","w3":"إلغاء التسلسل الزمني","practice":"قارن نصين أدبيين من مرحلتين موثقتين وحدد عامل تطور مدعومًا بمصدر."},{"n":2,"skill":"الكلاسيكية في الشعر الحديث","passage":"يمكن دراسة المدرسة الكلاسيكية بمظاهر العناية بالوزن واللغة واستلهام الموروث في أعمال محددة، لكن لا يصح جعل كل قصيدة موزونة كلاسيكية تلقائيًا. يتطلب التصنيف مقارنة نصوص أصلية ومصادر نقدية موثقة.","prompt":"ما الدليل الأقوى لتصنيف قصيدة كلاسيكية؟","correct":"تحليل صورتها ولغتها ووزنها في سياقها","w1":"اسم الشاعر وحده","w2":"عدد أبياتها فقط","w3":"تاريخ عام دون نص","practice":"اختر قصيدة عربية حديثة موثقة وحلل سمتين كلاسيكيتين مع شاهدين."},{"n":3,"skill":"الرومنسية والتجربة الذاتية","passage":"تعنى بعض نصوص الرومنسية بالتجربة الذاتية والطبيعة والوجدان، لكن السمات تُستخرج من الأبيات لا العنوان وحده. مثال مستقل: «عاد المسافر للشاطئ وتذكّر صديقًا بعيدًا» يوضح الحنين ولا يمثل قصيدة تاريخية.","prompt":"ما الشعور الذي يعرضه المثال المستقل؟","correct":"الحنين","w1":"التشفي","w2":"اللامبالاة","w3":"الفخر بمباراة","practice":"استخرج صورة وجدانية موثقة من قصيدة رومنسية وفسر دور الطبيعة والسياق."},{"n":4,"skill":"الواقعية في الشعر الحديث","passage":"قد يتناول الشعر الواقعي حياة الناس والعمل والمشكلات الاجتماعية بأدوات فنية متنوعة، لكن وصف كل نص معاصر بالواقعية غير دقيق. في نموذج أصلي يعرض شاعر متخيل صعوبة تنقل عامل يوميًا بين بيته ومكان عمله دون تسمية واقعة تاريخية.","prompt":"ما سمة الواقعية في النموذج؟","correct":"الاهتمام بتجربة اجتماعية يومية","w1":"الحديث عن مخلوق خرافي","w2":"غياب الإنسان","w3":"تجاهل السياق","practice":"قارن قصيدة واقعية أصلية بأخرى رومنسية، وحدد شاهدًا على اختلاف النظرة إلى التجربة."},{"n":5,"skill":"المنفى في شعر البارودي","passage":"«خواطر في المنفى» للبارودي تحتاج أبياتها الصحيحة وسياق الشاعر قبل الجزم بصورة أو عاطفة. مثال مستقل: «نظر المسافر إلى رسالة من أهله فغلبته الذكريات» يوحي بالشوق لكنه ليس اقتباسًا من قصيدة البارودي.","prompt":"ما الشعور الدال في النص المستقل؟","correct":"الشوق إلى الأهل","w1":"التهكم","w2":"اللامبالاة","w3":"الرغبة في النوم فقط","practice":"من القصيدة الأصلية استخرج شاهدًا للحنين إلى الوطن واشرح صورة بلاغية صحيحة."},{"n":6,"skill":"بطاقة ترجمة للبارودي","passage":"عند كتابة ترجمة محمود سامي البارودي ينبغي توثيق الميلاد والأعمال والسياقات الأدبية من مراجع موثوقة، وعدم دمج أحداث سيرته في بيت لا يوجد في الديوان. تؤثر السيرة في فهم النص حين يذكر الباحث المصدر بدقة.","prompt":"ما الممارسة الصحيحة في الترجمة؟","correct":"الرجوع إلى مصدر محقق وديوان موثق","w1":"اختلاق تاريخ","w2":"نقل شائعة","w3":"الاعتماد على عنوان فقط","practice":"أعد بطاقة ترجمة للبارودي تشمل أعمالًا مثبتة ومصدرين وسمتين فنيتين بشواهد."},{"n":7,"skill":"العروض: البحر البسيط","passage":"يتكون البسيط التام في الأصل من «مستفعلن فاعلن مستفعلن فاعلن» في كل شطر قبل صور الزحاف والعلة. يعتمد التقطيع على المتحركات والسواكن، ولا يتحدد البحر من حرف الروي.","prompt":"ما تفعيلة بداية البسيط؟","correct":"مستفعلن","w1":"فعولن","w2":"متفاعلن","w3":"مفاعلتن","practice":"قطّع بيتًا موثقًا على البسيط كتابة عروضية وحدد موضع تغيير واحد إن وُجد."},{"n":8,"skill":"مناقشة مقالة الزيات بمصدر موثق","passage":"«الإسلام دين القوة» للزيات عنوان نص فكري لا يجوز اختلاق عباراته أو نسبة حكم شرعي إليه من مجرد العنوان. يركز التدريب على استخراج الأطروحة والحجة وقياس قوة الدليل من النص المدرسي الصحيح، مع التفريق بين رأي الكاتب والمصادر الدينية.","prompt":"ما الذي يثبت أطروحة الكاتب في النص؟","correct":"عبارة موثقة مقرونة بحجة","w1":"عنوان المقال فقط","w2":"تلخيص تخميني","w3":"شاهد غير موجود","practice":"بعد الاطلاع على النص الأصلي، استخرج الفكرة الرئيسة وحجتين مع التحقق من أي اقتباس ديني."},{"n":9,"skill":"قراءة «المساء» لخليل مطران","passage":"يحتاج نص «المساء» لخليل مطران إلى أبياته المقررة لتحليل عاطفة الشاعر والطبيعة والتشبيه، ولا يصح تأليف بيت له. نموذج مستقل: «توارى ضوء النهار فوق البحر وهدأ صوت المراكب»، يعرض وصفًا حسّيًا لا يمثّل القصيدة.","prompt":"ما التفصيل الحسي في المثال المستقل؟","correct":"تراجع الضوء وهدوء الأصوات","w1":"اسم الشاعر","w2":"عنوان القصيدة","w3":"الوزن الصرفي","practice":"استخرج من القصيدة الأصلية صورة طبيعية بشاهد صحيح وفسر أثرها في الموقف الوجداني."},{"n":10,"skill":"العروض: البحر الخفيف","passage":"يتكون الخفيف التام في إحدى صوره الأصلية من «فاعلاتن مستفعلن فاعلاتن» لكل شطر قبل التغييرات العروضية المعروفة. التقطيع مرتبط بالنطق وحركات الكلمة في السياق، ويحتاج مرجعًا لتفسير الزحافات والعلل.","prompt":"ما التفعيلة الوسطى في الخفيف التام؟","correct":"مستفعلن","w1":"فعولن","w2":"متفاعلن","w3":"فاعلن","practice":"اختر بيتًا موثقًا على الخفيف وقطعه مع تحديد التفعيلات في كل شطر وملاحظة الاختلافات."},{"n":11,"skill":"الإصرار في شعر فدوى طوقان","passage":"تحليل «إباء وإصرار» لفدوى طوقان يتطلب النص الأصلي لتحديد الصوت الشعري وموضوع الإصرار وصوره؛ فالعنوان لا يثبت وحده رأيًا أو حدثًا. مثال مستقل: «حاولت طالبة تصحيح مشروعها ثلاث مرات حتى نجح» يوضح المثابرة دون أن يكون شعرًا.","prompt":"ما السلوك الذي يدل على الإصرار في المثال؟","correct":"تكرار المحاولة والتصحيح","w1":"إلغاء المشروع","w2":"إخفاء النتائج","w3":"رفض التعلم","practice":"استخرج من النص المقرر صورة شعرية موثقة تدل على العزيمة واشرح سياقها."},{"n":12,"skill":"العمل والاجتهاد في نص مسرحي","passage":"نص «لكل مجتهد نصيب» المنسوب إلى توفيق الحكيم يحتاج قراءة النص الحقيقي لمعرفة الشخصيات ونبرة الحوار والمفارقة، ولا يصح اختلاق نهاية. في مشهد مستقل: يتعاون فريق قبل مسابقة ويكتشف أن التدريب ساعدهم على معالجة الخطأ في الوقت المناسب.","prompt":"ما دور التدريب في المشهد المستقل؟","correct":"تحسين قدرة الفريق على معالجة الخطأ","w1":"ضمان نتيجة دون جهد","w2":"إلغاء المشكلات","w3":"منع التعاون","practice":"بعد قراءة النص المسرحي المقرر استخرج موقفًا حقيقيًا للشخصية وشاهدًا على العمل أو المثابرة."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=12
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='4611ec73-1e1a-4571-9c51-05d7c901c83f'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='أدب 311 — الأدب والنصوص والعروض' AND u.semester=1 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثاني عشر، الفصل الأول. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثاني عشر%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G12_T1_ADAB311_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.correct,r.w3) ELSE jsonb_build_array(r.w1,r.w2,r.w3,r.correct) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G12_T1_ADAB311_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G12_T1_ADAB311_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G12_T1_ADAB311_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;